int zero = 0;
int non_zero = 42;

if (zero) { /* false */ }
if (non_zero) { /* true */ }

double pi = 3.14;
if (pi) { /* true */ }

int* ptr_null = nullptr;
if (ptr_null) { /* false (null) */ }

int* ptr_valid = &non_zero;
if (ptr_valid) { /* true (non-null) */ }

enum Status { OK = 1, ERR = 0 };
if (ERR) { /* false (0) */ }
if (OK) { /* true (1) */ }

